25	interface RawResponse {
26	  status: number;
27	  headers: http.IncomingHttpHeaders;
28	  body: string;
29	}
30	
31	const request = (
32	  port: number,
33	  path: string,
34	  agent?: http.Agent,
35	): Promise<RawResponse> =>
36	  new Promise<RawResponse>((resolve, reject) => {
37	    http
38	      .get(
39	        `http://localhost:${port}${path}`,
40	        agent
41	          ? { agent }
42	          : {
43	              // Explicitly close connection after response to speed up server shutdown
44	              headers: { Connection: 'close' },
45	            },
46	        res => {
47	          let body = '';
48	          res.on('data', chunk => (body += chunk));
49	          res.on('end', () =>
50	            resolve({
51	              status: res.statusCode || 0,
52	              headers: res.headers,
53	              body,
54	            }),
55	          );
56	        },
57	      )
58	      .on('error', reject);
59	  });
60	
61	const post = (
62	  port: number,
63	  path: string,
64	  body: string,
65	  agent?: http.Agent,
66	): Promise<RawResponse> =>
67	  new Promise<RawResponse>((resolve, reject) => {
68	    const req = http.request(
69	      `http://localhost:${port}${path}`,
70	      {
71	        method: 'POST',
72	        agent,
73	        headers: {
74	          'Content-Type': 'application/json',
75	          'Content-Length': Buffer.byteLength(body),
76	          ...(agent ? {} : { Connection: 'close' }),
77	        },
78	      },
79	      res => {
80	        let data = '';
81	        res.on('data', chunk => (data += chunk));
82	        res.on('end', () =>
83	          resolve({
84	            status: res.statusCode || 0,
85	            headers: res.headers,
86	            body: data,
87	          }),
88	        );
89	      },
90	    );
91	    req.on('error', reject);
92	    req.end(body);
93	  });
