95	const counters = {
96	  guard: 0,
97	  pipe: 0,
98	  interceptor: 0,
99	  handler: 0,
100	};
101	
102	@Injectable()
103	class CountingGuard implements CanActivate {
104	  canActivate() {
105	    counters.guard++;
106	    return true;
107	  }
108	}
109	
110	@Injectable()
111	class CountingPipe implements PipeTransform {
112	  transform(value: unknown) {
113	    counters.pipe++;
114	    return value;
115	  }
116	}
117	
118	@Injectable()
119	class CountingInterceptor implements NestInterceptor {
120	  intercept(_context: ExecutionContext, next: CallHandler): Observable<any> {
121	    counters.interceptor++;
122	    return next.handle();
123	  }
124	}
125	
126	@Controller()
127	class SideEffectController {
128	  @Get('slow')
129	  async slow(@Query('q', CountingPipe) _q?: string) {
130	    counters.handler++;
131	    // Simulate work
132	    await new Promise(resolve => setTimeout(resolve, 500));
133	    return 'ok';
134	  }
135	
136	  @Get('boom')
137	  async boom() {
138	    await new Promise(resolve => setTimeout(resolve, 100));
139	    throw new Error('boom');
140	  }
141	}
142	
143	@Module({
144	  controllers: [SideEffectController],
145	})
146	class SideEffectModule {}
147	
148	describe('Graceful Shutdown (Fastify)', () => {
149	  let app: INestApplication;
150	
151	  afterEach(async () => {
152	    if (app) {
153	      await app.close();
154	    }
155	  });
156	
157	  it('should allow in-flight requests to complete when return503OnClosing is enabled', async () => {
158	    app = await NestFactory.create<NestFastifyApplication>(
159	      AppModule,
160	      new FastifyAdapter(),
161	      {
162	        return503OnClosing: true,
163	        logger: false,
164	      },
165	    );
166	    await app.listen(0);
167	    const port = app.getHttpServer().address().port;
168	
169	    const requestPromise = request(port, '/slow');
170	
171	    // Wait to ensure request is processing
172	    await new Promise(r => setTimeout(r, 100));
173	
174	    const closePromise = app.close();
175	
176	    // The in-flight request should finish successfully
177	    const response = await requestPromise;
178	    expect(response.status).toBe(200);
179	    expect(response.body).toBe('ok');
180	
181	    await closePromise;
182	  }, 10000);
183	
184	  it('should return 503 for NEW queued requests on existing connections during shutdown', async () => {
185	    app = await NestFactory.create<NestFastifyApplication>(
186	      AppModule,
187	      new FastifyAdapter(),
188	      {
189	        return503OnClosing: true,
190	        logger: false,
191	      },
192	    );
193	    await app.listen(0);
194	    const port = app.getHttpServer().address().port;
195	
196	    // Force 1 socket to ensure queuing/reuse
197	    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
198	
199	    // 1. Send Request A (slow) - occupies the socket
200	    const requestA = request(port, '/slow', agent);
201	
202	    // 2. Wait so Request A is definitely "in flight"
203	    await new Promise(r => setTimeout(r, 100));
204	
205	    // 3. Trigger Shutdown (don't await yet)
206	    const closePromise = app.close();
207	
208	    // Allow the microtask for prepareClose() to flush (sets isShuttingDown)
209	    await new Promise(r => setTimeout(r, 0));
210	
211	    // 4. Send Request B immediately using the same agent.
212	    const requestB = request(port, '/slow', agent);
213	
