233	    app = await NestFactory.create<NestFastifyApplication>(
234	      SideEffectModule,
235	      new FastifyAdapter(),
236	      {
237	        return503OnClosing: true,
238	        logger: false,
239	      },
240	    );
241	    app.useGlobalGuards(new CountingGuard());
242	    app.useGlobalInterceptors(new CountingInterceptor());
243	    await app.listen(0);
244	    const port = app.getHttpServer().address().port;
245	
246	    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
247	
248	    // Request A (slow) occupies the only socket
