250	    await new Promise(r => setTimeout(r, 100));
251	
252	    const closePromise = app.close();
253	    await new Promise(r => setTimeout(r, 0));
254	
255	    // Request B is queued on the same connection and arrives after the
256	    // shutdown state has been established
257	    const requestB = request(port, '/slow?q=2', agent);
258	
259	    const responseA = await requestA;
260	    expect(responseA.status).toBe(200);
261	
262	    const responseB = await requestB;
263	    expect(responseB.status).toBe(503);
264	    expect(responseB.body).toBe('Service Unavailable');
