528	
529	    const echoed = await new Promise<RawResponse>((resolve, reject) => {
530	      const body = JSON.stringify({ hello: 'world' });
531	      const req = http.request(
532	        `http://localhost:${port}/echo`,
533	        {
534	          method: 'POST',
535	          headers: {
536	            'Content-Type': 'application/json',
537	            'Content-Length': Buffer.byteLength(body),
